use rusqlite::{params,Connection,OptionalExtension};
use serde::{Deserialize,Serialize};
use std::{fs,path::PathBuf,sync::Mutex};
use tauri::Manager;
const API_VERSION:&str="1";const SCHEMA_VERSION:&str="1";const INDEX_VERSION:&str="1";const INDEX_FILE:&str="retrieval-index-v1.sqlite";const MAX_QUERY_LENGTH:usize=4096;const MAX_LIMIT:usize=100;
#[derive(Debug,Deserialize,Serialize,Clone,Copy,PartialEq,Eq)]#[serde(rename_all="snake_case")]pub enum RetrievalSource{CoreBook,Memory}
impl RetrievalSource{fn as_str(self)->&'static str{match self{Self::CoreBook=>"core_book",Self::Memory=>"memory"}}}
#[derive(Debug,Deserialize,Clone)]pub struct RetrievalFilters{pub status:Option<String>,#[serde(rename="type")]pub memory_type:Option<String>,pub tags:Option<Vec<String>>}
#[derive(Debug,Deserialize,Clone)]pub struct RetrievalQuery{#[serde(rename="apiVersion")]pub api_version:String,#[serde(rename="schemaVersion")]pub schema_version:String,#[serde(rename="characterId")]pub character_id:String,pub query:String,pub sources:Option<Vec<RetrievalSource>>,pub limit:Option<usize>,pub filters:Option<RetrievalFilters>}
#[derive(Debug,Serialize,Clone)]pub struct RetrievalMatch{pub field:String,pub text:String}
#[derive(Debug,Serialize,Clone)]pub struct RetrievalCandidate{pub source:RetrievalSource,#[serde(rename="sourceId")]pub source_id:String,#[serde(rename="characterId")]pub character_id:String,pub score:f64,#[serde(rename="matchedText")]pub matched_text:String,pub matches:Vec<RetrievalMatch>,pub metadata:RetrievalMetadata}
#[derive(Debug,Serialize,Clone)]pub struct RetrievalMetadata{pub title:Option<String>,pub status:Option<String>,#[serde(rename="type")]pub memory_type:Option<String>,#[serde(rename="updatedAt")]pub updated_at:String}
#[derive(Debug,Serialize,Clone)]pub struct RetrievalResult{#[serde(rename="apiVersion")]pub api_version:String,#[serde(rename="schemaVersion")]pub schema_version:String,#[serde(rename="characterId")]pub character_id:String,pub query:String,pub candidates:Vec<RetrievalCandidate>,pub degraded:bool,pub error:Option<String>}
#[derive(Debug,Deserialize,Serialize,Clone)]pub struct RetrievalIndexDocument{#[serde(rename="apiVersion")]pub api_version:String,#[serde(rename="schemaVersion")]pub schema_version:String,#[serde(rename="characterId")]pub character_id:String,pub source:RetrievalSource,#[serde(rename="sourceId")]pub source_id:String,pub title:String,pub content:String,pub tags:Vec<String>,pub status:Option<String>,#[serde(rename="type")]pub memory_type:Option<String>,#[serde(rename="updatedAt")]pub updated_at:String}
#[derive(Default)]pub struct RetrievalIndexLock(pub Mutex<()>);
fn config_dir(app:&tauri::AppHandle)->Result<PathBuf,String>{let dir=app.path().app_config_dir().map_err(|e|format!("failed to resolve app config directory: {e}"))?;fs::create_dir_all(&dir).map_err(|e|format!("failed to create app config directory: {e}"))?;Ok(dir)}
fn db_path(app:&tauri::AppHandle)->Result<PathBuf,String>{Ok(config_dir(app)?.join(INDEX_FILE))}
fn validate_document(d:&RetrievalIndexDocument)->Result<(),String>{if d.api_version!=API_VERSION||d.schema_version!=SCHEMA_VERSION{return Err("unsupported retrieval index document version".into())}if d.character_id.trim().is_empty()||d.character_id.len()>200{return Err("retrieval characterId is invalid".into())}if d.source_id.trim().is_empty()||d.source_id.len()>200{return Err("retrieval sourceId is invalid".into())}if d.title.len()>200{return Err("retrieval title is too long".into())}if d.tags.len()>32||d.tags.iter().any(|x|x.trim().is_empty()||x.len()>64){return Err("retrieval tags are invalid".into())}if d.updated_at.trim().is_empty(){return Err("retrieval updatedAt is required".into())}match d.source{RetrievalSource::CoreBook=>{if d.status.as_deref()!=Some("enabled")||d.memory_type.is_some(){return Err("invalid Core Book retrieval document state".into())}},RetrievalSource::Memory=>{if d.status.as_deref()!=Some("active")||d.memory_type.is_none(){return Err("invalid Memory retrieval document state".into())}}}Ok(())}
fn validate_query(q:&RetrievalQuery)->Result<(String,usize),String>{if q.api_version!=API_VERSION||q.schema_version!=SCHEMA_VERSION{return Err("unsupported retrieval query version".into())}let scope=q.character_id.trim();if scope.is_empty()||scope.len()>200{return Err("retrieval characterId is invalid".into())}if q.query.trim().is_empty()||q.query.len()>MAX_QUERY_LENGTH{return Err("retrieval query is empty or too long".into())}let limit=q.limit.unwrap_or(20).min(MAX_LIMIT);if limit==0{return Err("retrieval limit must be positive".into())}if q.sources.as_ref().is_some_and(|s|s.is_empty()){return Err("retrieval sources must not be empty".into())}Ok((scope.to_string(),limit))}
fn tokenize_query(q:&str)->Vec<String>{let mut out=Vec::new();let mut cur=String::new();for ch in q.chars(){if ch.is_alphanumeric()||ch=='_'{cur.push(ch)}else if !cur.is_empty(){out.push(std::mem::take(&mut cur))}}if !cur.is_empty(){out.push(cur)}out.into_iter().take(64).collect()}
fn fts_quote(v:&str)->String{format!("\"{}\"",v.replace('"',"\"\""))}
fn build_match_query(q:&str)->Option<String>{let t=tokenize_query(q);if t.is_empty(){return None}let mut parts=Vec::new();if t.len()>1{parts.push(fts_quote(&t.join(" ")))}parts.extend(t.iter().map(|x|fts_quote(x)));Some(parts.join(" OR "))}
fn initialize_schema(conn:&Connection)->Result<(),String>{conn.execute_batch("CREATE TABLE IF NOT EXISTS retrieval_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);").map_err(|e|format!("failed to create retrieval metadata: {e}"))?;let v:Option<String>=conn.query_row("SELECT value FROM retrieval_meta WHERE key='indexVersion'",[],|r|r.get(0)).optional().map_err(|e|format!("failed to read retrieval index version: {e}"))?;if v.as_deref()!=Some(INDEX_VERSION){conn.execute_batch("DROP TABLE IF EXISTS retrieval_fts;DROP TABLE IF EXISTS retrieval_documents;DELETE FROM retrieval_meta;").map_err(|e|format!("failed to reset retrieval index: {e}"))?}conn.execute_batch("CREATE TABLE IF NOT EXISTS retrieval_meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);INSERT OR REPLACE INTO retrieval_meta(key,value) VALUES('indexVersion','1');CREATE TABLE IF NOT EXISTS retrieval_documents(rowid INTEGER PRIMARY KEY,character_id TEXT NOT NULL,source TEXT NOT NULL,source_id TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,tags TEXT NOT NULL,status TEXT,type TEXT,updated_at TEXT NOT NULL,UNIQUE(character_id,source,source_id));CREATE VIRTUAL TABLE IF NOT EXISTS retrieval_fts USING fts5(title,content,tags,content='retrieval_documents',content_rowid='rowid',tokenize='unicode61 remove_diacritics 1');").map_err(|e|format!("failed to initialize retrieval index: {e}"))?;let status:Option<String>=conn.query_row("SELECT value FROM retrieval_meta WHERE key='status'",[],|r|r.get(0)).optional().map_err(|e|format!("failed to read retrieval status: {e}"))?;if status.is_none(){conn.execute("INSERT INTO retrieval_meta(key,value) VALUES('status','degraded')",[]).map_err(|e|format!("failed to initialize retrieval status: {e}"))?;}Ok(())}
fn open(app:&tauri::AppHandle)->Result<Connection,String>{let conn=Connection::open(db_path(app)?).map_err(|e|format!("failed to open retrieval index: {e}"))?;initialize_schema(&conn)?;Ok(conn)}
fn remove_row(conn:&Connection,c:&str,s:RetrievalSource,id:&str)->Result<(),String>{let row:Option<(i64,String,String,String)>=conn.query_row("SELECT rowid,title,content,tags FROM retrieval_documents WHERE character_id=?1 AND source=?2 AND source_id=?3",params![c,s.as_str(),id],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).optional().map_err(|e|format!("failed to locate retrieval document: {e}"))?;if let Some((rowid,title,content,tags))=row{conn.execute("INSERT INTO retrieval_fts(retrieval_fts,rowid,title,content,tags) VALUES('delete',?1,?2,?3,?4)",params![rowid,title,content,tags]).map_err(|e|format!("failed to remove retrieval FTS row: {e}"))?;conn.execute("DELETE FROM retrieval_documents WHERE rowid=?1",params![rowid]).map_err(|e|format!("failed to remove retrieval document: {e}"))?;}Ok(())}
fn upsert_inner(conn:&Connection,d:&RetrievalIndexDocument)->Result<(),String>{validate_document(d)?;remove_row(conn,&d.character_id,d.source,&d.source_id)?;let tags=serde_json::to_string(&d.tags).map_err(|e|e.to_string())?;conn.execute("INSERT INTO retrieval_documents(character_id,source,source_id,title,content,tags,status,type,updated_at)VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9)",params![d.character_id,d.source.as_str(),d.source_id,d.title,d.content,tags,d.status,d.memory_type,d.updated_at]).map_err(|e|format!("failed to write retrieval document: {e}"))?;let rowid=conn.last_insert_rowid();conn.execute("INSERT INTO retrieval_fts(rowid,title,content,tags)VALUES(?1,?2,?3,?4)",params![rowid,d.title,d.content,d.tags.join(" ")]).map_err(|e|format!("failed to write retrieval FTS row: {e}"))?;Ok(())}
fn source_ok(s:RetrievalSource,sources:&Option<Vec<RetrievalSource>>)->bool{sources.as_ref().map(|x|x.contains(&s)).unwrap_or(true)}
fn search_inner(conn:&Connection,q:&RetrievalQuery)->Result<RetrievalResult,String>{let(char_id,limit)=validate_query(q)?;let m=match build_match_query(&q.query){Some(x)=>x,None=>return Ok(RetrievalResult{api_version:API_VERSION.into(),schema_version:SCHEMA_VERSION.into(),character_id:char_id,query:q.query.clone(),candidates:Vec::new(),degraded:false,error:None})};let status:Option<String>=conn.query_row("SELECT value FROM retrieval_meta WHERE key='status'",[],|r|r.get(0)).optional().map_err(|e|e.to_string())?;let degraded=status.as_deref()!=Some("ready");let error=degraded.then(||"Retrieval index is degraded or requires rebuild.".to_string());let mut st=conn.prepare("SELECT d.source,d.source_id,d.character_id,-bm25(f,8.0,5.0,3.0),snippet(f,1,'[[MATCH]]','[[/MATCH]]','...',18),highlight(f,0,'[[MATCH]]','[[/MATCH]]'),highlight(f,2,'[[MATCH]]','[[/MATCH]]'),d.title,d.tags,d.status,d.type,d.updated_at FROM retrieval_fts f JOIN retrieval_documents d ON d.rowid=f.rowid WHERE f MATCH ?1 AND d.character_id=?2 ORDER BY 4 DESC,d.source ASC,d.source_id ASC LIMIT 500").map_err(|e|e.to_string())?;let mut rows=st.query(params![m,char_id]).map_err(|e|e.to_string())?;let mut out=Vec::new();while let Some(r)=rows.next().map_err(|e|e.to_string())?{let source=match r.get::<_,String>(0).map_err(|e|e.to_string())?.as_str(){"core_book"=>RetrievalSource::CoreBook,"memory"=>RetrievalSource::Memory,_=>continue};if !source_ok(source,&q.sources){continue}let source_id:String=r.get(1).map_err(|e|e.to_string())?;let row_char:String=r.get(2).map_err(|e|e.to_string())?;if row_char!=char_id{continue}let score:f64=r.get(3).map_err(|e|e.to_string())?;let content:String=r.get(4).unwrap_or_default();let title_h:String=r.get(5).unwrap_or_default();let tags_h:String=r.get(6).unwrap_or_default();let title:String=r.get(7).unwrap_or_default();let tags_raw:String=r.get(8).unwrap_or_default();let status:Option<String>=r.get(9).unwrap_or(None);let mem_type:Option<String>=r.get(10).unwrap_or(None);let updated_at:String=r.get(11).unwrap_or_default();if let Some(f)=&q.filters{if f.status.as_ref().is_some_and(|x|status.as_deref()!=Some(x.as_str())){continue}if f.memory_type.as_ref().is_some_and(|x|source==RetrievalSource::Memory&&mem_type.as_deref()!=Some(x.as_str())){continue}if let Some(tags)=&f.tags{let indexed:Vec<String>=serde_json::from_str(&tags_raw).unwrap_or_default();if !tags.iter().all(|x|indexed.iter().any(|y|y.eq_ignore_ascii_case(x))){continue}}}let mut matches=Vec::new();if title_h.contains("[[MATCH]]"){matches.push(RetrievalMatch{field:"title".into(),text:title_h})}if content.contains("[[MATCH]]"){matches.push(RetrievalMatch{field:"content".into(),text:content})}if tags_h.contains("[[MATCH]]"){matches.push(RetrievalMatch{field:"tags".into(),text:tags_h})}let matched_text=matches.first().map(|x|x.text.clone()).unwrap_or_else(||title.clone());out.push(RetrievalCandidate{source,source_id,character_id:row_char,score,matched_text,matches,metadata:RetrievalMetadata{title:(!title.is_empty()).then_some(title),status,memory_type:mem_type,updated_at}});if out.len()>=limit{break}}Ok(RetrievalResult{api_version:API_VERSION.into(),schema_version:SCHEMA_VERSION.into(),character_id:char_id,query:q.query.clone(),candidates:out,degraded,error})}
fn clear_character(conn:&Connection,c:&str)->Result<(),String>{let rows:Vec<(i64,String,String,String)>=conn.prepare("SELECT rowid,title,content,tags FROM retrieval_documents WHERE character_id=?1").map_err(|e|e.to_string())?.query_map(params![c],|r|Ok((r.get(0)?,r.get(1)?,r.get(2)?,r.get(3)?))).map_err(|e|e.to_string())?.collect::<Result<Vec<_>,_>>().map_err(|e|e.to_string())?;for(rowid,title,content,tags)in rows{conn.execute("INSERT INTO retrieval_fts(retrieval_fts,rowid,title,content,tags)VALUES('delete',?1,?2,?3,?4)",params![rowid,title,content,tags]).map_err(|e|e.to_string())?;}conn.execute("DELETE FROM retrieval_documents WHERE character_id=?1",params![c]).map_err(|e|e.to_string())?;Ok(())}
fn rebuild(conn:&mut Connection,scope:Option<&str>,docs:&[RetrievalIndexDocument])->Result<(),String>{let tx=conn.transaction().map_err(|e|e.to_string())?;if let Some(c)=scope{clear_character(&tx,c)?}else{tx.execute_batch("DROP TABLE IF EXISTS retrieval_fts;DROP TABLE IF EXISTS retrieval_documents;CREATE TABLE retrieval_documents(rowid INTEGER PRIMARY KEY,character_id TEXT NOT NULL,source TEXT NOT NULL,source_id TEXT NOT NULL,title TEXT NOT NULL,content TEXT NOT NULL,tags TEXT NOT NULL,status TEXT,type TEXT,updated_at TEXT NOT NULL,UNIQUE(character_id,source,source_id));CREATE VIRTUAL TABLE retrieval_fts USING fts5(title,content,tags,content='retrieval_documents',content_rowid='rowid',tokenize='unicode61 remove_diacritics 1');").map_err(|e|e.to_string())?}for d in docs{validate_document(d)?;if scope.is_some_and(|c|c!=d.character_id){continue}let tags=serde_json::to_string(&d.tags).map_err(|e|e.to_string())?;tx.execute("INSERT INTO retrieval_documents(character_id,source,source_id,title,content,tags,status,type,updated_at)VALUES(?1,?2,?3,?4,?5,?6,?7,?8,?9)",params![d.character_id,d.source.as_str(),d.source_id,d.title,d.content,tags,d.status,d.memory_type,d.updated_at]).map_err(|e|e.to_string())?;let rowid=tx.last_insert_rowid();tx.execute("INSERT INTO retrieval_fts(rowid,title,content,tags)VALUES(?1,?2,?3,?4)",params![rowid,d.title,d.content,d.tags.join(" ")]).map_err(|e|e.to_string())?;}tx.execute("INSERT OR REPLACE INTO retrieval_meta(key,value)VALUES('status','ready')",[]).map_err(|e|e.to_string())?;tx.commit().map_err(|e|e.to_string())?;Ok(())}
fn core_doc(e:&crate::core_book::CoreBookEntry)->Option<RetrievalIndexDocument>{e.enabled.then(||RetrievalIndexDocument{api_version:API_VERSION.into(),schema_version:SCHEMA_VERSION.into(),character_id:e.character_id.clone(),source:RetrievalSource::CoreBook,source_id:e.id.clone(),title:e.title.clone(),content:e.content.clone(),tags:e.tags.clone(),status:Some("enabled".into()),memory_type:None,updated_at:e.updated_at.clone()})}
fn mem_doc(e:&crate::memory::MemoryItem)->Option<RetrievalIndexDocument>{if !matches!(e.status,crate::memory::MemoryStatus::Active){return None}let typ=match e.memory_type{crate::memory::MemoryType::Fact=>"fact",crate::memory::MemoryType::Preference=>"preference",crate::memory::MemoryType::Relationship=>"relationship",crate::memory::MemoryType::Event=>"event",crate::memory::MemoryType::Experience=>"experience",crate::memory::MemoryType::Goal=>"goal",crate::memory::MemoryType::Instruction=>"instruction",crate::memory::MemoryType::Observation=>"observation"};Some(RetrievalIndexDocument{api_version:API_VERSION.into(),schema_version:SCHEMA_VERSION.into(),character_id:e.character_id.clone(),source:RetrievalSource::Memory,source_id:e.id.clone(),title:String::new(),content:e.content.clone(),tags:e.tags.clone(),status:Some("active".into()),memory_type:Some(typ.into()),updated_at:e.updated_at.clone()})}
fn load_docs(app:&tauri::AppHandle,c:&str,ml:&crate::memory::MemoryWriteLock)->Result<Vec<RetrievalIndexDocument>,String>{let mut docs=Vec::new();if let Some(s)=crate::core_book::load(app,c)?{for e in &s.entries{if let Some(d)=core_doc(e){docs.push(d)}}}if let Some(s)=crate::memory::load(app,c,ml)?{for e in &s.items{if let Some(d)=mem_doc(e){docs.push(d)}}}docs.sort_by(|a,b|a.source.as_str().cmp(b.source.as_str()).then(a.source_id.cmp(&b.source_id)));Ok(docs)}
pub fn search(app:&tauri::AppHandle,q:&RetrievalQuery,l:&RetrievalIndexLock)->Result<RetrievalResult,String>{let _g=l.0.lock().map_err(|_|"retrieval index lock poisoned".to_string())?;search_inner(&open(app)?,q)}
pub fn rebuild_character(app:&tauri::AppHandle,c:&str,l:&RetrievalIndexLock,ml:&crate::memory::MemoryWriteLock)->Result<(),String>{let _g=l.0.lock().map_err(|_|"retrieval index lock poisoned".to_string())?;let c=c.trim();if c.is_empty(){return Err("character id must not be empty".into())}let docs=load_docs(app,c,ml)?;rebuild(&mut open(app)?,Some(c),&docs)}
pub fn rebuild_all(app:&tauri::AppHandle,l:&RetrievalIndexLock,ml:&crate::memory::MemoryWriteLock)->Result<(),String>{let _g=l.0.lock().map_err(|_|"retrieval index lock poisoned".to_string())?;let chars=crate::characters::load(app)?.ok_or_else(||"character storage is not available for retrieval rebuild".to_string())?;let mut docs=Vec::new();for c in &chars.characters{docs.extend(load_docs(app,&c.id,ml)?)}rebuild(&mut open(app)?,None,&docs)}
pub fn upsert(app:&tauri::AppHandle,d:&RetrievalIndexDocument,l:&RetrievalIndexLock)->Result<(),String>{let _g=l.0.lock().map_err(|_|"retrieval index lock poisoned".to_string())?;upsert_inner(&open(app)?,d)}
pub fn remove(app:&tauri::AppHandle,c:&str,s:&RetrievalSource,id:&str,l:&RetrievalIndexLock)->Result<(),String>{let _g=l.0.lock().map_err(|_|"retrieval index lock poisoned".to_string())?;remove_row(&open(app)?,c.trim(),*s,id.trim())}
pub fn remove_character(app:&tauri::AppHandle,c:&str,l:&RetrievalIndexLock)->Result<(),String>{let _g=l.0.lock().map_err(|_|"retrieval index lock poisoned".to_string())?;clear_character(&open(app)?,c.trim())}
#[cfg(test)]
mod tests{
  use super::*;
  fn doc(character:&str,source:RetrievalSource,id:&str,title:&str,content:&str,tags:&[&str],status:&str,kind:Option<&str>)->RetrievalIndexDocument{
    RetrievalIndexDocument{api_version:API_VERSION.into(),schema_version:SCHEMA_VERSION.into(),character_id:character.into(),source,source_id:id.into(),title:title.into(),content:content.into(),tags:tags.iter().map(|x|(*x).into()).collect(),status:Some(status.into()),memory_type:kind.map(|x|x.into()),updated_at:"2026-09-26T12:00:00.000Z".into()}
  }
  fn query(character:&str,text:&str,sources:Option<Vec<RetrievalSource>>,limit:usize,filters:Option<RetrievalFilters>)->RetrievalQuery{
    RetrievalQuery{api_version:API_VERSION.into(),schema_version:SCHEMA_VERSION.into(),character_id:character.into(),query:text.into(),sources,limit:Some(limit),filters}
  }
  fn conn()->Connection{let c=Connection::open_in_memory().unwrap();initialize_schema(&c).unwrap();c}
  #[test]fn injection_safe(){let q=build_match_query("Berlin OR sqlite").unwrap();assert!(!q.contains(" OR sqlite"));assert!(q.contains("\"Berlin\""));assert!(q.contains("\"sqlite\""))}
  #[test]fn phrase_query_contains_phrase(){assert!(build_match_query("Berlin Munich").unwrap().contains("\"Berlin Munich\""))}
  #[test]fn fts_search_is_character_scoped_and_title_weighted(){
    let mut c=conn();
    let docs=[
      doc("a",RetrievalSource::CoreBook,"a-title","Berlin","Berlin is a city",&["city"],"enabled",None),
      doc("a",RetrievalSource::Memory,"a-memory","","I remember Berlin from a trip",&["travel"],"active",Some("event")),
      doc("b",RetrievalSource::CoreBook,"b-title","Berlin","other character",&["city"],"enabled",None),
      doc("a",RetrievalSource::Memory,"a-tag","","A travel preference",&["Berlin"],"active",Some("preference"))
    ];
    rebuild(&mut c,None,&docs).unwrap();
    let result=search_inner(&c,&query("a","Berlin",None,10,None)).unwrap();
    assert!(result.candidates.iter().all(|x|x.character_id=="a"));
    assert_eq!(result.candidates.first().unwrap().source_id,"a-title");
    assert!(result.candidates.iter().any(|x|x.source_id=="a-tag"));
  }
  #[test]fn filters_and_deterministic_tie_break(){
    let mut c=conn();
    let docs=[
      doc("a",RetrievalSource::Memory,"b","","alpha beta",&["tag"],"active",Some("fact")),
      doc("a",RetrievalSource::Memory,"a","","alpha beta",&["tag"],"active",Some("fact")),
      doc("a",RetrievalSource::Memory,"z","","alpha beta",&["other"],"archived",Some("fact")),
      doc("a",RetrievalSource::CoreBook,"core","alpha beta","alpha beta",&["tag"],"enabled",None)
    ];
    rebuild(&mut c,None,&docs).unwrap();
    let filters=RetrievalFilters{status:Some("active".into()),memory_type:Some("fact".into()),tags:Some(vec!["tag".into()])};
    let result=search_inner(&c,&query("a","alpha beta",Some(vec![RetrievalSource::Memory]),2,Some(filters))).unwrap();
    assert_eq!(result.candidates.len(),2);assert_eq!(result.candidates[0].source_id,"a");assert_eq!(result.candidates[1].source_id,"b");
  }
  #[test]fn missing_index_is_degraded_and_rebuild_restores_results(){
    let mut c=conn();
    let docs=[doc("a",RetrievalSource::CoreBook,"core","Berlin","Berlin lore",&["city"],"enabled",None)];
    rebuild(&mut c,None,&docs).unwrap();
    assert_eq!(search_inner(&c,&query("a","Berlin",None,10,None)).unwrap().candidates.len(),1);
    c.execute_batch("DROP TABLE retrieval_fts;DROP TABLE retrieval_documents;").unwrap();
    initialize_schema(&c).unwrap();
    assert!(search_inner(&c,&query("a","Berlin",None,10,None)).unwrap().degraded);
    rebuild(&mut c,None,&docs).unwrap();
    let restored=search_inner(&c,&query("a","Berlin",None,10,None)).unwrap();
    assert!(!restored.degraded);assert_eq!(restored.candidates.len(),1);
  }
  #[test]fn restart_preserves_derived_index(){
    let path=std::env::temp_dir().join(format!("nova-retrieval-{}-{}.sqlite",std::process::id(),12345));
    let _=std::fs::remove_file(&path);
    {let mut c=Connection::open(&path).unwrap();initialize_schema(&c).unwrap();rebuild(&mut c,None,&[doc("a",RetrievalSource::Memory,"m","","Munich Berlin",&["travel"],"active",Some("fact"))]).unwrap();}
    {let c=Connection::open(&path).unwrap();initialize_schema(&c).unwrap();let r=search_inner(&c,&query("a","Munich",None,10,None)).unwrap();assert!(!r.degraded);assert_eq!(r.candidates[0].source_id,"m");}
    let _=std::fs::remove_file(&path);
  }
}
